  key = theme_service->GetColorProviderKey(key, profile);
  key.custom_theme = GetCustomTheme();
#if BUILDFLAG(ENABLE_AUX_BROWSER)
  // GetCustomTheme selects the actual window/extension supplier after the
  // ThemeService key. Restore the opt-in Aux wrapper on that final supplier;
  // otherwise background/tint mixers and their contrast marker are discarded.
  // Native privacy and explicit widget color overrides retain precedence.
  if (!IsIncognitoBrowser() && !IsEnterpriseIsolatedModeBrowser() &&
      !user_color_override().has_value()) {
    key = aux_theme::DecorateColorProviderKey(profile, std::move(key));
  }
#endif
